import BufferView from '../../viewer.mjs'
import { encodeString } from '../../utils/strings.mjs'

export function parse (bytes) {
  const view = new BufferView(bytes)
  return view.getString(8, view.byteLength - 8, 'utf8')
}

export function validate (value) {
  if (typeof value !== 'string') {
    throw new Error('`data` value is not a string')
  }
}

export function encode (value) {
  const bytes = []
  const strBytes = encodeString(value)
  const view = new BufferView(8)
  view.setUint32(0, 1)
  view.setUint32(4, 0)
  bytes.push(...view.getUint8(0, 8), ...strBytes)
  return bytes
}
